head.script:
scwin.count = 0;
scwin.onpageload = function () {

};

scwin.onpageunload = function () {

};


scwin.trigger1_onclick = function (e) {
    scwin.count++;
    var winObj = {
        title: "300x300",
        src: "window_src.xml",
        windowTitle: "300x300_Title",
        windowId: "300xd00_Id" + scwin.count,
        frameMode: "wframe",
        defaultWidth: "300",
        defaultHeight: "300"
    }
    windowContainer1.createWindow(winObj);
};

scwin.trigger2_onclick = function (e) {
    scwin.count++;
    var winObj = {
        title: "200x200",
        src: "window_src.xml",
        windowTitle: "200x200_Title",
        windowId: "200x200_Id" + scwin.count,
        frameMode: "wframe",
        defaultWidth: "200",
        defaultHeight: "200"
    }
    windowContainer1.createWindow(winObj);
};
